# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, factor=2):
    return [v * factor for v in xs[1:]]

# region: emit
def emit(xs, offset=-1):
    return [v + offset for v in xs]

# region: shape
def shape(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: gather
def gather(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(digest(shape(emit(fold(intake(raw))))))

