import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 0.0, 'max': 0, 'label': 'ALPHA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 0.5, 'max': 2, 'label': 'ALPHA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 0.6666666666666666, 'max': 2, 'label': 'ALPHA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 4.0, 'max': 4, 'label': 'ALPHA'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 1.3333333333333333, 'max': 2, 'label': 'ALPHA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 0.0, 'max': 0, 'label': 'ALPHA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 0.0, 'max': 0, 'label': 'ALPHA'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'mean': 3.3333333333333335, 'max': 8, 'label': 'ALPHA'})

if __name__ == '__main__':
    unittest.main()
